/* pvz_state.h: pvz-rl shared state, schema v1 (step 1.1).
 * GENERATED by `python -m schema.gen --write` from pvz-rl schema/spec.py. Do not edit.
 * The emulator fork carries a byte-identical copy of pvz_state.h at schema/pvz_state.h.
 *
 * The contract between the emulator adapter (x64, MSVC), the real-game harness (i686,
 * LLVM-MinGW) and the Python agent (NumPy dtype schema.PVZ_STATE_DTYPE).
 *
 * Layout rules
 * - Only int32_t, uint32_t, float (32-bit) and uint8_t[n] with n a multiple of 4. Enums
 *   stored as int32_t. Alignment 4 everywhere; no #pragma pack; explicit _pad fields
 *   written as zero. Little-endian.
 * - Every offset and sizeof is asserted below.
 * - Arrays: count + fixed capacity; entries [0,count) live, ascending slot order; bytes
 *   in [count,cap) unspecified, never read, not zeroed; overflow = number of live
 *   entries that did not fit (first cap written, count = cap).
 * - Units: ticks at 100/s; pixels float32 in each world's own frame (plant int -> float
 *   exact); row/col 0-based, row 0 top. Producers pass pixel values through unchanged.
 * - Codes: plant/zombie/grid-item/accessory TYPE codes = the emulator enum values. STATUS
 *   codes are carried raw (status_raw, world-specific) and encoder v1 must not read them.
 * - valid bitmask: a producer sets a group's bit only if it filled every field in the
 *   group; the harness only if every address it read is VERIFIED.
 * - Any layout change bumps PVZ_STATE_VERSION; the bridge handshake checks magic,
 *   version, layout hash and size.
 */
#pragma once

#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
#define PVZ_STATIC_ASSERT(cond, msg) static_assert(cond, msg)
#else
#define PVZ_STATIC_ASSERT(cond, msg) _Static_assert(cond, msg)
#endif

/* ---- version, size, handshake ---- */
#define PVZ_STATE_VERSION     1
#define PVZ_STATE_SIZE        59848       /* bytes */
#define PVZ_STATE_LAYOUT_HASH 0x428a9a89u /* first 4 bytes of the spec sha256 */
#define PVZ_STATE_MAGIC       1398429264u /* ASCII "PVZS" as a little-endian uint32 (design constant) */

/* ---- array capacities (design choices) ---- */
#define PVZ_MAX_CARDS     10
#define PVZ_MAX_PLANTS    256
#define PVZ_MAX_ZOMBIES   512
#define PVZ_MAX_GRIDITEMS 128
#define PVZ_MAX_MOWERS    8

/* ---- world codes ---- */
