/* ---- valid bits: index (BIT_) and mask ---- */
#define PVZ_VALID_BIT_CORE             0
#define PVZ_VALID_CORE                 1u          /* tick, sun, scene, paused */
#define PVZ_VALID_BIT_PHASE            1
#define PVZ_VALID_PHASE                2u          /* phase */
#define PVZ_VALID_BIT_GAME_OVER        2
#define PVZ_VALID_GAME_OVER            4u
