#define PVZ_VALID_GRID_COUNTDOWN       134217728u  /* countdown_raw */
#define PVZ_VALID_BIT_MOWERS           28
#define PVZ_VALID_MOWERS               268435456u  /* mowers[] */

/* ---- plant_flag bits: index (BIT_) and mask ---- */
#define PVZ_PLANT_FLAG_BIT_SLEEPING 0
#define PVZ_PLANT_FLAG_SLEEPING     1u
