PVZ_STATIC_ASSERT(offsetof(pvz_state_t, hdr) == 0, "pvz_state_t.hdr");
PVZ_STATIC_ASSERT(offsetof(pvz_state_t, cards) == 128, "pvz_state_t.cards");
PVZ_STATIC_ASSERT(offsetof(pvz_state_t, plants) == 328, "pvz_state_t.plants");
